const KEY='motabe_v19';
const oldKeys=['motabe_v16','motabe_v15','motabe_v14','motabe_v13','motabe_v12','motabe_v11','motabe_v1'];
const empty={trainer:{name:'',department:'',formUrl:''},courses:[],departmentReports:[],headSettings:{college:'',department:'',academicYear:'',headName:'',formUrl:'',expectedTrainers:[]}};
function load(){try{let raw=localStorage.getItem(KEY);if(!raw){for(const k of oldKeys){if(localStorage.getItem(k)){raw=localStorage.getItem(k);break}}}let d=raw?JSON.parse(raw):structuredClone(empty);d.trainer??={name:'',department:'',formUrl:''};d.trainer.department??='';d.trainer.formUrl??='';d.courses??=[];d.departmentReports??=[];d.headSettings??={college:'',department:'',academicYear:'',headName:'',formUrl:'',expectedTrainers:[]};d.headSettings.department??='';d.headSettings.formUrl??='';d.headSettings.expectedTrainers??=[];d.courses.forEach(normalizeCourse);return d}catch{return structuredClone(empty)}}
function normalizeCourse(c){c.specialty??='';c.sections??=[];c.weeks??=[];c.skills??=[];c.students??=[];c.tracking??={};c.skills=c.skills.slice(0,30).map((s,i)=>typeof s==='string'?{id:'sk'+Date.now()+i,name:s,week:null}:s);c.students=c.students.map((s,i)=>typeof s==='string'?{id:'st'+i,name:s,number:''}:s)}
let db=load(),view='home',currentCourse=0,headMode='week',currentVisibleRows=[];
const app=document.querySelector('#app');
function save(){localStorage.setItem(KEY,JSON.stringify(db))}
function home(){app.innerHTML=`<section class='hero'><h1>متابع</h1><p>منصة متابعة المهارات العملية</p></section><div class='grid'><div class='card role' onclick="view='trainer';render()"><h2>مدرب</h2><p class='muted'>إدارة المقررات والشعب ومتابعة تطبيق المهارات لكل متدرب</p></div><div class='card role' onclick="view='head';render()"><h2>رئيس قسم</h2><p class='muted'>تجميع تقارير المدربين ومتابعة مؤشرات القسم دون استلام البيانات الفردية</p></div></div>`}
function trainer(){let cards=db.courses.map((c,i)=>{let s=courseStats(c);return `<div class='card course'><div class='between row'><div><h3>${esc(c.name)}</h3>${c.specialty?`<span class='badge'>${esc(c.specialty)}</span>`:''}<span class='badge'>${esc(c.code||'بدون رمز')}</span><span class='badge'>${c.sections.length} شعب</span></div><button class='ghost' onclick='openCourse(${i})'>فتح</button></div><p class='muted'>${esc(c.sections.join('، ')||'لم تضف شعب بعد')}</p><div class='skill-summary'><div class='mini-card'>المتدربون<b>${c.students.length}</b></div><div class='mini-card'>المهارات<b>${c.skills.length}</b></div><div class='mini-card'>الإنجاز<b>${numPct(s.interaction)}</b></div></div></div>`}).join('');app.innerHTML=`<div class='row between'><div><div class='title'>لوحة المدرب</div><div class='muted'>${db.trainer.name?`المدرب: ${esc(db.trainer.name)}`:'أضف اسم المدرب قبل تصدير التقارير.'}</div></div><div class='row'><button class='ghost' onclick="view='home';render()">الرئيسية</button><button class='ghost' onclick='trainerProfile()'>بيانات المدرب</button><button class='ghost' onclick="formLinkDialog('trainer')">رابط فورم القسم</button><button class='ghost' onclick="clearDataDialog('trainer')">مسح البيانات</button><button class='btn' onclick='addCourse()'>+ إضافة مقرر</button></div></div><div class='notice'>بيانات المتدربين والمتابعة تحفظ محليًا على هذا المتصفح. تقرير رئيس القسم يحتوي مؤشرات إجمالية فقط.</div><div class='grid'>${cards||`<div class='card'><h3>ابدأ بأول مقرر</h3><p class='muted'>أضف المقرر ثم استورد متدربيه ومهاراته أو أدخلهم يدويًا.</p></div>`}</div>`}
function trainerProfile(){modal(`<h2>بيانات المدرب</h2><div class='formgrid'><label>اسم المدرب<input id='tn' value='${esc(db.trainer.name)}'><small class='field-note'>ملاحظة: لابد من كتابة اسم المدرب ثلاثيًا كما هو بالنظام لضمان تطابقه مع بيانات رئيس القسم</small></label><label>القسم<input id='td' value='${esc(db.trainer.department||'')}'></label></div><div class='row mt'><button class='btn' onclick='saveTrainer()'>حفظ</button><button class='ghost' onclick='closeModal()'>إلغاء</button></div>`)}
function saveTrainer(){db.trainer.name=v('tn');db.trainer.department=v('td');save();closeModal();trainer()}
function addCourse(){modal(`<h2>إضافة مقرر</h2><div class='formgrid'><label>التخصص<input id='csp' placeholder='مثال: الدعم الفني'></label><label>اسم المقرر<input id='cn'></label><label>رمز المقرر<input id='cc'></label><label>الشعب (افصل بينها بفاصلة)<input id='cs'></label></div><div class='row mt'><button class='btn' onclick='saveCourse()'>حفظ</button><button class='ghost' onclick='closeModal()'>إلغاء</button></div>`)}
function saveCourse(){let name=v('cn');if(!name)return alert('اكتب اسم المقرر');db.courses.push({name,specialty:v('csp'),code:v('cc'),sections:v('cs').split(/[,،]/).map(x=>x.trim()).filter(Boolean),weeks:[],skills:[],students:[],tracking:{}});save();closeModal();trainer()}
function openCourse(i,tab='track'){currentCourse=i;let c=db.courses[i];normalizeCourse(c);let s=courseStats(c);app.innerHTML=`<div class='row between'><div><div class='title'>${esc(c.name)}</div><div class='muted'>${c.specialty?`التخصص: ${esc(c.specialty)} — `:''}${esc(c.code||'')} — الشعب: ${esc(c.sections.join('، ')||'—')}</div></div><div class='course-actions trainer-nav'><button class='ghost' onclick='trainer()'>رجوع</button><button class='ghost' onclick="view='home';render()">الرئيسية</button><button class='ghost' onclick='editCourse(${i})'>إعدادات المقرر</button><button class='ghost' onclick='importTechni(${i})'>استيراد من منصة تقني</button><button class='ghost' onclick='importBlackboard(${i})'>استيراد من Blackboard Ultra</button></div></div><div class='skill-summary'><div class='mini-card'>المتدربون<b>${c.students.length}</b></div><div class='mini-card'>المهارات<b>${c.skills.length}</b></div><div class='mini-card'>إجمالي التفعيلات<b>${s.done}</b><small>عبر جميع المهارات</small></div><div class='mini-card'>متدربون يحتاجون متابعة<b>${s.need}</b><small>لديهم مهارة واحدة أو أكثر غير مفعلة</small></div><div class='mini-card' id='currentSkillKpi'>إنجاز المهارة الحالية<b>—</b><small>اختر مهارة لعرض النسبة</small></div></div><div class='skill-tabs'><button class='${tab==='track'?'active':''}' onclick="openCourse(${i},'track')">المتابعة</button><button class='${tab==='skills'?'active':''}' onclick="openCourse(${i},'skills')">مهارات المقرر</button><button class='${tab==='students'?'active':''}' onclick="openCourse(${i},'students')">المتدربون</button><button class='${tab==='reports'?'active':''}' onclick="openCourse(${i},'reports')">التقارير</button></div><div id='courseBody'></div>`; if(tab==='track')renderTracking(i);if(tab==='skills')renderSkills(i);if(tab==='students')renderStudents(i);if(tab==='reports')renderCourseReports(i)}
function editCourse(i){let c=db.courses[i];modal(`<h2>إعدادات المقرر</h2><div class='formgrid'><label>التخصص<input id='ecsp' value='${esc(c.specialty||'')}'></label><label>اسم المقرر<input id='ecn' value='${esc(c.name)}'></label><label>الرمز<input id='ecc' value='${esc(c.code||'')}'></label><label>الشعب<input id='ecs' value='${esc(c.sections.join('، '))}'></label></div><div class='row mt'><button class='btn' onclick='saveCourseEdit(${i})'>حفظ</button><button class='ghost' onclick='closeModal()'>إلغاء</button></div>`)}
function saveCourseEdit(i){let c=db.courses[i];c.name=v('ecn')||c.name;c.specialty=v('ecsp');c.code=v('ecc');c.sections=v('ecs').split(/[,،]/).map(x=>x.trim()).filter(Boolean);save();closeModal();openCourse(i)}
function renderSkills(i){let c=db.courses[i];let rows=c.skills.map((s,n)=>`<tr><td>${n+1}</td><td>${esc(s.name)}</td><td>${s.week||'—'}</td><td><button class='ghost compact' onclick='editSkill(${i},"${s.id}")'>تعديل</button> <button class='ghost danger-text compact' onclick='deleteSkill(${i},"${s.id}")'>حذف</button></td></tr>`).join('');document.querySelector('#courseBody').innerHTML=`<div class='card'><div class='row between'><div><h3>خطة مهارات المقرر</h3><p class='muted'>أضف مهارات المقرر واربط كل مهارة بأسبوع اختياري</p></div><button class='btn' onclick='addSkill(${i})' ${c.skills.length>=30?'disabled':''}>+ إضافة مهارة</button></div><div class='tablewrap'><table><thead><tr><th>#</th><th>المهارة</th><th>الأسبوع</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan=4>لا توجد مهارات بعد.</td></tr>'}</tbody></table></div></div>`}
function addSkill(i){let c=db.courses[i];if(c.skills.length>=30)return alert('الحد الأعلى 30 مهارة للمقرر');modal(`<h2>إضافة مهارة</h2><div class='formgrid'><label>اسم المهارة<input id='skn'></label><label>الأسبوع المخطط (اختياري)<input id='skw' type='number' min='1' max='17'></label></div><div class='row mt'><button class='btn' onclick='saveSkill(${i})'>حفظ</button><button class='ghost' onclick='closeModal()'>إلغاء</button></div>`)}
function saveSkill(i){let name=v('skn'),week=+v('skw')||null;if(!name)return alert('اكتب اسم المهارة');let c=db.courses[i];if(c.skills.length>=30)return alert('وصلت للحد الأعلى');c.skills.push({id:uid('sk'),name,week});save();closeModal();openCourse(i,'skills')}
function editSkill(i,id){let s=db.courses[i].skills.find(x=>x.id===id);modal(`<h2>تعديل المهارة</h2><div class='formgrid'><label>اسم المهارة<input id='skn' value='${esc(s.name)}'></label><label>الأسبوع<input id='skw' type='number' min='1' max='17' value='${s.week||''}'></label></div><div class='row mt'><button class='btn' onclick='saveSkillEdit(${i},"${id}")'>حفظ</button><button class='ghost' onclick='closeModal()'>إلغاء</button></div>`)}
function saveSkillEdit(i,id){let s=db.courses[i].skills.find(x=>x.id===id);s.name=v('skn')||s.name;s.week=+v('skw')||null;save();closeModal();openCourse(i,'skills')}
function deleteSkill(i,id){if(!confirm('حذف المهارة وحالاتها المسجلة؟'))return;let c=db.courses[i];c.skills=c.skills.filter(x=>x.id!==id);Object.values(c.tracking).forEach(t=>delete t[id]);save();openCourse(i,'skills')}
function renderStudents(i){let c=db.courses[i];let rows=c.students.map((s,n)=>`<tr><td>${n+1}</td><td>${esc(s.name)}</td><td>${esc(s.number||'—')}</td><td><button class='ghost danger-text compact' onclick='deleteStudent(${i},"${s.id}")'>حذف</button></td></tr>`).join('');document.querySelector('#courseBody').innerHTML=`<div class='card'><div class='row between'><div><h3>قائمة المتدربين</h3><p class='muted'>تبقى ثابتة للمقرر طوال الفصل ما لم تحذفها أو تحدثها أنت.</p></div><div class='row'><button class='ghost' onclick='addStudent(${i})'>+ إضافة يدوي</button><button class='ghost' onclick='importTechni(${i})'>استيراد من منصة تقني</button><button class='ghost' onclick='importBlackboard(${i})'>استيراد من Blackboard Ultra</button></div></div><div class='tablewrap'><table><thead><tr><th>#</th><th>اسم المتدرب</th><th>الرقم</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan=4>لا توجد أسماء بعد.</td></tr>'}</tbody></table></div></div>`}
function addStudent(i){modal(`<h2>إضافة متدرب</h2><div class='formgrid'><label>الاسم<input id='stn'></label><label>الرقم/اسم المستخدم<input id='sti'></label></div><div class='row mt'><button class='btn' onclick='saveStudent(${i})'>حفظ</button><button class='ghost' onclick='closeModal()'>إلغاء</button></div>`)}
function saveStudent(i){let name=v('stn'),number=v('sti');if(!name)return alert('اكتب الاسم');let c=db.courses[i];let existing=number&&c.students.find(s=>s.number===number);if(existing)existing.name=name;else c.students.push({id:uid('st'),name,number});save();closeModal();openCourse(i,'students')}
function deleteStudent(i,id){if(!confirm('حذف المتدرب من هذا المقرر؟'))return;let c=db.courses[i];c.students=c.students.filter(x=>x.id!==id);delete c.tracking[id];save();openCourse(i,'students')}
function renderTracking(i){let c=db.courses[i];if(!c.students.length||!c.skills.length){document.querySelector('#courseBody').innerHTML=`<div class='card'><h3>ابدأ المتابعة</h3><p class='muted'>أضف/استورد المتدربين ثم أضف مهارات المقرر. أضف/استورد المتدربين ثم أضف مهارات المقرر</p><div class='row'><button class='btn' onclick='importTechni(${i})'>استيراد ملف تقني</button><button class='ghost' onclick="openCourse(${i},'skills')">إضافة المهارات</button></div></div>`;return}let skillOpts=c.skills.map(s=>`<option value='${s.id}'>${esc(s.name)}${s.week?' — أسبوع '+s.week:''}</option>`).join('');document.querySelector('#courseBody').innerHTML=`<div class='card'><div class='row between'><div><h3>متابعة تطبيق المهارات</h3><p class='muted'>اختر المهارة ثم حدّث الحالات. أي حالة مستوردة تلقائيًا تبقى قابلة للتعديل.</p></div><label style='min-width:280px'>المهارة<select id='trackSkill' onchange='renderSkillRoster(${i})'>${skillOpts}</select></label></div><div id='skillRoster'></div></div>`;renderSkillRoster(i)}
function renderSkillRoster(i){let c=db.courses[i],sid=document.querySelector('#trackSkill')?.value||c.skills[0]?.id,skill=c.skills.find(s=>s.id===sid);if(!skill)return;let rows=c.students.map((st,n)=>{let status=c.tracking?.[st.id]?.[sid]||'pending';return `<tr><td>${n+1}</td><td>${esc(st.name)}<div class='tiny'>${esc(st.number||'')}</div></td><td><select class='status-select ${statusClass(status)}' onchange='setStatus(${i},"${st.id}","${sid}",this.value,this)'>${statusOptions(status)}</select></td></tr>`}).join('');let counts=countSkill(c,sid);document.querySelector('#skillRoster').innerHTML=`<div class='row mt'><button class='ghost compact' onclick='setAllStatus(${i},"${sid}","done")'>تحديد الكل مفعل</button><button class='ghost compact' onclick='setAllStatus(${i},"${sid}","pending")'>مسح تحديد الكل</button><span id='skillCounts'><span class='badge'>مفعل ${counts.done}</span><span class='badge'>لم يفعل ${counts.notdone}</span><span class='badge'>غائب ${counts.absent}</span><span class='badge'>حرمان ${counts.deprived}</span><span class='badge'>لم يحدد ${counts.pending}</span></span></div><div class='skills-scroll topgap'><table class='skill-table'><thead><tr><th>#</th><th>المتدرب</th><th>${esc(skill.name)}</th></tr></thead><tbody>${rows}</tbody></table></div>`;updateCurrentSkillKpi(c,sid)}
function setStatus(i,stid,sid,status,el){let c=db.courses[i];c.tracking[stid]??={};c.tracking[stid][sid]=status;save();if(el)el.className='status-select '+statusClass(status);updateCurrentSkillKpi(c,sid);updateSkillBadges(c,sid)}
function setAllStatus(i,sid,status){let c=db.courses[i];c.students.forEach(st=>{c.tracking[st.id]??={};c.tracking[st.id][sid]=status});save();renderSkillRoster(i)}
function statusOptions(sel){return [['pending','— لم يحدد'],['done','مفعل'],['notdone','لم يفعل'],['absent','غائب'],['deprived','حرمان']].map(([v,t])=>`<option value='${v}' ${sel===v?'selected':''}>${t}</option>`).join('')}
function statusClass(s){return 'status-'+s}
function countSkill(c,sid){let o={done:0,notdone:0,absent:0,deprived:0,pending:0};c.students.forEach(st=>o[c.tracking?.[st.id]?.[sid]||'pending']++);o.counted=o.done+o.notdone+o.absent;o.interaction=o.counted?o.done/o.counted*100:null;return o}
function courseStats(c){let done=0,needSet=new Set(),counted=0;for(const st of c.students){for(const sk of c.skills){let x=c.tracking?.[st.id]?.[sk.id]||'pending';if(x==='done'){done++;counted++}else if(x==='notdone'){counted++;needSet.add(st.id)}else if(x==='absent'){counted++;needSet.add(st.id)}}}return {done,need:needSet.size,interaction:counted?done/counted*100:null}}
function updateCurrentSkillKpi(c,sid){let x=countSkill(c,sid),box=document.querySelector('#currentSkillKpi');if(!box)return;box.innerHTML=`إنجاز المهارة الحالية<b>${numPct(x.interaction)}</b><small>${x.done} مفعل من ${x.counted} محتسب${x.deprived?` — ${x.deprived} حرمان مستبعد`:''}</small>`}
function updateSkillBadges(c,sid){let x=countSkill(c,sid);document.querySelector('#skillCounts')?.replaceChildren();let el=document.querySelector('#skillCounts');if(el)el.innerHTML=`<span class='badge'>مفعل ${x.done}</span><span class='badge'>لم يفعل ${x.notdone}</span><span class='badge'>غائب ${x.absent}</span><span class='badge'>حرمان ${x.deprived}</span><span class='badge'>لم يحدد ${x.pending}</span>`}
function importTechni(i){modal(`<h2>استيراد من منصة تقني</h2><div class='importbox'><p><b>ملف التقديرات من منصة تقني</b> أو ملف أسماء متدربين</p><p class='muted'>يقرأ الملف داخل المتصفح. الأعمدة التي تبدأ بـ «واجب:» تُضاف كمهارات، والدرجة الفعلية تعني «مفعل». الشرطة (-) أو الخلية الفارغة تبقى «لم يحدد» لتعديلها يدويًا.</p><input id='xlsxFile' type='file' accept='.xlsx,.xls,.csv'></div><p class='muted'>لن يحذف الاستيراد أسماء موجودة مسبقًا</p><div class='row mt'><button class='btn' onclick='processExcel(${i})'>تحليل واستيراد</button><button class='ghost' onclick='closeModal()'>إلغاء</button></div>`)}
async function processExcel(i){let f=document.getElementById('xlsxFile')?.files?.[0];if(!f)return alert('اختر ملف Excel');try{let rows=await readSpreadsheetLocally(f);if(!rows.length)return alert('الملف لا يحتوي بيانات');let c=db.courses[i],headers=Object.keys(rows[0]);let nameCol=headers.find(h=>/الاسم الأول|اسم المتدرب|الاسم/i.test(h)),numCol=headers.find(h=>/اسم المستخدم|الرقم التدريبي|رقم المتدرب/i.test(h)),skillCols=headers.filter(h=>/^واجب:/i.test(h)&&!/إجمالي/i.test(h));if(!nameCol)return alert('لم أتعرف على عمود اسم المتدرب');let newSkills=0,newStudents=0,autoDone=0;let skillMap={};for(const h of skillCols){let clean=h.replace(/^واجب:/i,'').replace(/\s*\(حقيقي\)\s*$/,'').trim();let sk=c.skills.find(s=>norm(s.name)===norm(clean));if(!sk&&c.skills.length<30){sk={id:uid('sk'),name:clean,week:null};c.skills.push(sk);newSkills++}if(sk)skillMap[h]=sk.id}for(const r of rows){let name=String(r[nameCol]||'').trim();if(!name)continue;let number=numCol?String(r[numCol]||'').trim():'';let st=(number&&c.students.find(s=>s.number===number))||c.students.find(s=>norm(s.name)===norm(name));if(!st){st={id:uid('st'),name,number};c.students.push(st);newStudents++}else{st.name=name;if(number)st.number=number}c.tracking[st.id]??={};for(const [h,sid] of Object.entries(skillMap)){let val=r[h];if(hasGrade(val)){c.tracking[st.id][sid]='done';autoDone++}else if(!c.tracking[st.id][sid])c.tracking[st.id][sid]='pending'}}save();closeModal();alert(`تم الاستيراد بنجاح\nمتدربون جدد: ${newStudents}\nمهارات جديدة: ${newSkills}\nحالات «مفعل» من درجات فعلية: ${autoDone}${skillCols.length>Object.keys(skillMap).length?'\nتم تجاهل مهارات زائدة لأن الحد الأعلى 30':''}`);openCourse(i,'track')}catch(e){console.error(e);alert('تعذر قراءة الملف، تأكد أن الملف بصيغة xlsx أو csv')}}
let pendingBlackboardImport=null;
function importBlackboard(i){modal(`<h2>استيراد من Blackboard Ultra</h2><div class='importbox'><p><b>ملف دفتر التقديرات الكامل من Blackboard Ultra</b></p><p class='muted'>يحلل متابع الملف أولًا ويعرض الأنشطة المحتملة، ثم تختار بنفسك المهارات التي تريد استيرادها. لن تُضاف أي مهارة قبل اختيارك.</p><input id='bbFile' type='file' accept='.xls,.xlsx,.csv'></div><p class='muted'>الملف يبقى داخل المتصفح ولا يُرفع إلى خادم متابع</p><div class='row mt'><button class='btn' onclick='analyzeBlackboard(${i})'>تحليل الملف</button><button class='ghost' onclick='closeModal()'>إلغاء</button></div>`) }
async function analyzeBlackboard(i){let f=document.getElementById('bbFile')?.files?.[0];if(!f)return alert('اختر ملف Blackboard Ultra');try{let rows=await readSpreadsheetLocally(f);if(!rows.length)return alert('الملف لا يحتوي بيانات');let headers=Object.keys(rows[0]);let nameCol=headers.find(h=>/^الاسم الأول$/i.test(h))||headers.find(h=>/اسم المتدرب|الاسم/i.test(h)),numCol=headers.find(h=>/^معرف الطالب$/i.test(h))||headers.find(h=>/^اسم المستخدم$/i.test(h));if(!nameCol)return alert('لم أتعرف على عمود اسم المتدرب في ملف Blackboard');let candidates=headers.filter(h=>/إجمالي النقاط\s*:\s*1(?:\D|$)/i.test(h)&&!/Total|إجمالي|التقدير الإجمالي/i.test(h.split('[')[0]));if(!candidates.length)return alert('لم أجد أنشطة محتملة بدرجة قصوى 1. يمكنك إضافة المهارات يدويًا.');pendingBlackboardImport={i,rows,nameCol,numCol,candidates};let checks=candidates.map((h,n)=>{let clean=String(h).split('[')[0].trim();return `<label class='bb-skill-choice'><input type='checkbox' class='bbSkillCheck' value='${n}'> <span>${esc(clean)}</span></label>`}).join('');modal(`<h2>حدد المهارات المراد استيرادها</h2><p class='muted'>وجد متابع ${candidates.length} نشاطًا محتملًا. حدد المهارات العملية فقط، واترك الاختبارات والأنشطة الأخرى بدون تحديد.</p><div class='importbox bb-skill-list'>${checks}</div><div class='row mt'><button class='btn' onclick='importSelectedBlackboardSkills()'>استيراد المهارات المحددة</button><button class='ghost' onclick='closeModal()'>إلغاء</button></div>`)}catch(e){console.error(e);alert('تعذر قراءة ملف Blackboard Ultra')}}
function importSelectedBlackboardSkills(){let x=pendingBlackboardImport;if(!x)return alert('أعد اختيار ملف Blackboard Ultra');let selected=[...document.querySelectorAll('.bbSkillCheck:checked')].map(el=>x.candidates[+el.value]).filter(Boolean);if(!selected.length)return alert('حدد مهارة واحدة على الأقل');let c=db.courses[x.i],newSkills=0,newStudents=0,autoDone=0,skillMap={};for(const h of selected){let clean=String(h).split('[')[0].trim();if(!clean)continue;let sk=c.skills.find(s=>norm(s.name)===norm(clean));if(!sk&&c.skills.length<30){sk={id:uid('sk'),name:clean,week:null};c.skills.push(sk);newSkills++}if(sk)skillMap[h]=sk.id}for(const r of x.rows){let name=cleanImportedText(r[x.nameCol]);if(!name)continue;let number=x.numCol?cleanImportedText(r[x.numCol]):'';let st=(number&&c.students.find(s=>s.number===number))||c.students.find(s=>norm(s.name)===norm(name));if(!st){st={id:uid('st'),name,number};c.students.push(st);newStudents++}else{st.name=name;if(number)st.number=number}c.tracking[st.id]??={};for(const [h,sid] of Object.entries(skillMap)){let val=String(r[h]??'').trim();if(val&&val!=='-'&&val!=='—'){c.tracking[st.id][sid]='done';autoDone++}else if(!c.tracking[st.id][sid])c.tracking[st.id][sid]='pending'}}save();pendingBlackboardImport=null;closeModal();alert(`تم استيراد Blackboard Ultra بنجاح\nمتدربون جدد: ${newStudents}\nمهارات محددة: ${selected.length}\nمهارات جديدة: ${newSkills}\nحالات «مفعل»: ${autoDone}`);openCourse(x.i,'track')}
function hasGrade(v){if(v===null||v===undefined)return false;let s=String(v).trim();if(!s||s==='-'||s==='—')return false;return !Number.isNaN(Number(s.replace(',','.')))||/ناجح|مكتمل|تم/i.test(s)}
function weeklyCourseStats(c,week){/* التقرير الأسبوعي يجب أن يحسب مهارات الأسبوع المختار فقط، لا الأسابيع السابقة */let skills=c.skills.filter(s=>Number(s.week)===Number(week)),done=0,notdone=0,absent=0,deprived=0,pending=0;for(const st of c.students){for(const sk of skills){let x=c.tracking?.[st.id]?.[sk.id]||'pending';if(x==='done')done++;else if(x==='notdone')notdone++;else if(x==='absent')absent++;else if(x==='deprived')deprived++;else pending++}}let counted=done+notdone+absent;return {skills,done,notdone,absent,deprived,pending,counted,students:c.students.length,interaction:counted?done/counted*100:null}}
function reportWeekState(){return document.querySelector('#rstate')?.value||'normal'}
function updateTrainerReportKpi(i){let c=db.courses[i],week=+(document.querySelector('#rw')?.value||1),x=weeklyCourseStats(c,week),state=reportWeekState();let el=document.querySelector('#trainerReportKpi');if(el){if(state==='no_skill')el.innerHTML=`حالة الأسبوع ${week}<b>لا توجد مهارة</b><small>تُسجل كإفادة ولا تدخل في نسبة تفاعل المتدربين</small>`;else if(state==='continuing')el.innerHTML=`حالة الأسبوع ${week}<b>مهارة مستمرة</b><small>تُسجل كإفادة ولا تدخل في نسبة تفاعل المتدربين لهذا الأسبوع</small>`;else el.innerHTML=x.skills.length?`نسبة الإنجاز للأسبوع ${week}<b>${numPct(x.interaction)}</b><small>${c.students.length} متدرب — ${x.skills.length} مهارة في هذا الأسبوع${x.deprived?` — ${x.deprived} حرمان مستبعد`:''}</small>`:`نسبة الإنجاز للأسبوع ${week}<b>—</b><small>لا توجد مهارة مرتبطة بهذا الأسبوع؛ اختر «لا توجد مهارة» قبل الإرسال</small>`}let sk=document.querySelector('#trainerReportSkills');if(sk)sk.textContent=state==='normal'?x.skills.length:'—'}
function renderCourseReports(i){let c=db.courses[i];let weeks=Array.from({length:17},(_,n)=>n+1);document.querySelector('#courseBody').innerHTML=`<div class='card'><h3>تقرير المتابعة</h3><p class='muted'>اختر حالة الأسبوع. «لا توجد مهارة» و«مهارة مستمرة» تعتبران إفادة للأسبوع ولا تدخلان في نسبة تفاعل المتدربين</p><div class='formgrid'><label>الأسبوع<select id='rw' onchange='updateTrainerReportKpi(${i})'>${weeks.map(w=>`<option>${w}</option>`).join('')}</select></label><label>حالة الأسبوع<select id='rstate' onchange='updateTrainerReportKpi(${i})'><option value='normal'>تقرير مهارة</option><option value='continuing'>مهارة مستمرة</option><option value='no_skill'>لا توجد مهارة هذا الأسبوع</option></select></label><label>الشهر<input id='rm' type='month'></label></div><div class='skill-summary'><div class='mini-card'>المتدربون<b>${c.students.length}</b></div><div class='mini-card'>المهارات المحتسبة<b id='trainerReportSkills'>—</b></div><div class='mini-card' id='trainerReportKpi'>نسبة الإنجاز<b>—</b></div></div><div class='row'><button class='btn' onclick='sendFormReport(${i})'>إرسال تقرير رئيس القسم</button><button class='ghost' onclick='downloadSkillReport(${i})'>تصدير JSON</button><button class='ghost' onclick="clearDataDialog('trainer')">مسح البيانات</button></div></div>`;updateTrainerReportKpi(i)}

function formLinkDialog(scope){let url=scope==='head'?(db.headSettings?.formUrl||''):(db.trainer?.formUrl||'');modal(`<h2>${scope==='head'?'إضافة رابط فورم':'رابط فورم القسم'}</h2><p class='muted'>ألصق رابط Microsoft Forms. لهذا النموذج المحفوظ في متابع لا يلزم تعبئة قيم تجريبية؛ متابع يضيف بيانات التقرير عند الإرسال.</p><label>رابط الفورم المعبأ مسبقًا<input id='formUrlInput' type='url' placeholder='https://forms.cloud.microsoft/r/... أو رابط ResponsePage' value='${esc(url)}'></label><div class='row mt'><button class='btn' onclick="saveFormLink('${scope}')">حفظ</button>${url?`<button class='ghost' onclick="window.open('${esc(url)}','_blank')">اختبار الرابط</button>`:''}<button class='ghost' onclick='closeModal()'>إلغاء</button></div>`)}
function isMicrosoftFormUrl(url){try{let u=new URL(url);return /(^|\.)(forms\.cloud\.microsoft|forms\.office\.com|forms\.microsoft\.com)$/i.test(u.hostname)}catch{return false}}
function saveFormLink(scope){let url=v('formUrlInput');if(url&&!/^https:\/\/(forms\.cloud\.microsoft|forms\.office|forms\.microsoft)\//i.test(url))return alert('أدخل رابط Microsoft Forms صحيح');if(url&&!isMicrosoftFormUrl(url))return alert('أدخل رابط Microsoft Forms صحيح');if(scope==='head'){db.headSettings.formUrl=url}else{db.trainer.formUrl=url}save();closeModal();scope==='head'?head():trainer()}
const FORM_FIELDS={trainer:'r892e34b8ace9484ea982efe13c61dc53',department:'r3a6fea9db8ea4b239bb55b27fc918521',course:'ra447cada23884676a08a3b93ee0370fb',code:'r3ac563b55412486bacd913ca193852cf',section:'r090feedfe092473d837f7dbd4c17a86d',week:'r285d5020173349ca8aea4665ef9c7499',total:'r06097780d2cb4820a40adb213a18471e',done:'r168cf4bbbe604ac5b8ced0d6328d15af',notdone:'r6c21c41f09394fa0aa0f536dfef33810',absent:'r29157867758443468a2b33d4cdfd0acd',deprived:'r0ba06258728e49e4a97e33a569dc15f8',rate:'r5eb4d9e4310341ab9214ee92c42fb7b4'};
function fillMicrosoftForm(url,data){let u=new URL(url);for(const key of Object.values(FORM_FIELDS))u.searchParams.delete(key);let base=u.toString();let parts=[];for(const [name,key] of Object.entries(FORM_FIELDS)){let value=String(data[name]??'');parts.push(encodeURIComponent(key)+'='+encodeURIComponent(value))}return base+(base.includes('?')?'&':'?')+parts.join('&')}
function sendFormReport(i){let url=db.trainer?.formUrl||'';if(!url)return formLinkDialog('trainer');if(!isMicrosoftFormUrl(url))return alert('أضف رابط Microsoft Forms صحيح أولًا');if(!db.trainer.name)return alert('أضف اسم المدرب أولًا');if(!db.trainer.department)return alert('أضف القسم من بيانات المدرب أولًا');let c=db.courses[i],week=+v('rw'),month=v('rm'),state=reportWeekState();if(!month)return alert('حدد الشهر');let x=weeklyCourseStats(c,week);if(state==='normal'&&!x.skills.length)return alert('لا توجد مهارة مرتبطة بهذا الأسبوع. اختر «لا توجد مهارة» أو «مهارة مستمرة»');let special=state!=='normal',rate=state==='no_skill'?'لا توجد مهارة':state==='continuing'?'مهارة مستمرة':(Number.isFinite(Number(x.interaction))?Number(x.interaction).toFixed(1):'');let finalUrl=fillMicrosoftForm(url,{trainer:db.trainer.name,department:db.trainer.department,course:(c.specialty?`[${c.specialty}] ${c.name}`:c.name),code:c.code||'',section:c.sections.join('، '),week,total:c.students.length,done:special?0:x.done,notdone:special?0:x.notdone,absent:special?0:x.absent,deprived:special?0:x.deprived,rate});window.open(finalUrl,'_blank')}

function expectedTrainerNames(){let x=db.headSettings?.expectedTrainers||[];return [...new Set(x.map(v=>cleanImportedText(v)).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ar'))}
function head(){let rs=db.departmentReports||[];for(const r of rs){r.trainer=cleanImportedText(r.trainer);r.department=cleanImportedText(r.department);r.course=cleanImportedText(r.course);r.code=cleanImportedText(r.code);r.sections=(r.sections||[]).map(cleanImportedText)}save();let months=[...new Set(rs.map(r=>r.month).filter(Boolean))].sort(),hs=db.headSettings||{},allTrainers=[...new Set([...expectedTrainerNames(),...rs.map(r=>r.trainer).filter(Boolean)])].sort((a,b)=>a.localeCompare(b,'ar'));app.innerHTML=`<div class='orghead'><img class='orglogo' src='tvtc-logo.jpeg'><div class='orgmeta'><h2>${esc(hs.college||'اسم الكلية')}</h2><div class='meta-grid'><div class='meta-item'><b>القسم</b>${esc(hs.department||'غير محدد')}</div><div class='meta-item'><b>العام التدريبي</b>${esc(hs.academicYear||'غير محدد')}</div><div class='meta-item'><b>رئيس القسم</b>${esc(hs.headName||'غير محدد')}</div></div></div><button class='ghost' onclick='headSettings()'>بيانات التقرير والمدربين</button></div><div class='row between'><div><div class='title'>لوحة رئيس القسم</div><div class='muted'>نزّل ملف Excel مرة أسبوعيًا ثم استورده هنا</div></div><div class='toolbar'><button class='ghost toolbarAction' onclick="view='home';render()">الرئيسية</button><label class='btn toolbarAction importAction'>استيراد ملف Excel<input type='file' accept='.xlsx,.xls,.csv' hidden onchange='importFormsExcel(this.files)'></label><button class='ghost toolbarAction' onclick="clearDataDialog('head')">مسح البيانات</button><select class='exportSelect toolbarAction' onchange='handleExportChoice(this)'><option value=''>تصدير التقرير</option><option value='excel'>Excel</option><option value='pdf'>PDF</option></select></div></div><div class='card filterbar'><div class='row'><button class='${headMode==='week'?'btn':'ghost'}' onclick="headMode='week';applyHead()">عرض أسبوعي</button><button class='${headMode==='month'?'btn':'ghost'}' onclick="headMode='month';applyHead()">عرض شهري</button><label class='filter'>الأسبوع<select id='hfWeek' onchange='applyHead()'>${Array.from({length:17},(_,i)=>`<option value='${i+1}'>الأسبوع ${i+1}</option>`).join('')}</select></label><label class='filter'>الشهر<select id='hfMonth' onchange='applyHead()'>${months.map(m=>`<option value='${m}'>${monthName(m)}</option>`).join('')||'<option value="">لا توجد أشهر</option>'}</select></label><label class='filter'>المدرب<select id='hfTrainer' onchange='applyHead()'><option value=''>كل المدربين</option>${allTrainers.map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><label class='filter grow'>بحث<input id='hfSearch' oninput='applyHead()'></label></div></div><div id='headResults'></div>`;let latest=[...new Set(rs.map(r=>+r.week).filter(Boolean))].sort((a,b)=>a-b).at(-1);if(latest)document.querySelector('#hfWeek').value=latest;if(months.length)document.querySelector('#hfMonth').value=months.at(-1);applyHead()}
function headSettings(){let h=db.headSettings||{},names=expectedTrainerNames().join('\n');modal(`<h2>بيانات التقرير والمدربين</h2><div class='formgrid'><label>اسم الكلية<input id='hCollege' value='${esc(h.college||'')}'></label><label>القسم<input id='hDepartment' value='${esc(h.department||'')}'></label><label>العام التدريبي<input id='hYear' value='${esc(h.academicYear||'')}'></label><label>اسم رئيس القسم<input id='hName' value='${esc(h.headName||'')}'></label></div><label class='mt'>المدربون المتوقع منهم الإفادة أسبوعيًا<textarea id='hExpected' rows='8' placeholder='اسم مدرب ثلاثي في كل سطر'>${esc(names)}</textarea></label><p class='muted'>ملاحظة: اكتب اسم كل مدرب ثلاثيًا كما هو بالنظام، وكل اسم في سطر جديد، لضمان مطابقته مع بيانات المدرب المستوردة</p><div class='row mt'><label class='ghost importAction'>استيراد أسماء المدربين<input type='file' accept='.xlsx,.xls,.csv' hidden onchange='importExpectedTrainers(this.files)'></label><span class='muted'>يمكن استيراد ملف يحتوي عمود اسم المدرب أو قائمة أسماء في عمود واحد</span></div><div class='row mt'><button class='btn' onclick='saveHeadSettings()'>حفظ</button><button class='ghost' onclick='closeModal()'>إلغاء</button></div>`)}
async function importExpectedTrainers(files){let f=files?.[0];if(!f)return;try{let rows=await readSpreadsheetLocally(f);if(!rows.length)return alert('الملف لا يحتوي أسماء');let headers=Object.keys(rows[0]),nameCol=headers.find(h=>/اسم\s*المدرب|المدرب|الاسم/i.test(h))||headers[0],names=rows.map(r=>cleanImportedText(r[nameCol])).filter(Boolean);if(!names.length)return alert('لم أجد أسماء مدربين في الملف');let current=(document.getElementById('hExpected')?.value||'').split(/\n/).map(cleanImportedText).filter(Boolean),all=[...new Set([...current,...names])];document.getElementById('hExpected').value=all.join('\n');alert(`تم استيراد ${names.length} اسمًا — راجع القائمة ثم اضغط حفظ`)}catch(e){console.error(e);alert('تعذر قراءة ملف أسماء المدربين')}}
function saveHeadSettings(){db.headSettings={...db.headSettings,college:v('hCollege'),department:v('hDepartment'),academicYear:v('hYear'),headName:v('hName'),expectedTrainers:(document.getElementById('hExpected')?.value||'').split(/\n/).map(x=>x.trim()).filter(Boolean)};save();closeModal();head()}
function getHeadFiltered(){let rs=db.departmentReports||[],week=+(document.querySelector('#hfWeek')?.value||1),month=document.querySelector('#hfMonth')?.value||'',trainer=document.querySelector('#hfTrainer')?.value||'',q=(document.querySelector('#hfSearch')?.value||'').trim().toLowerCase();return rs.filter(r=>(headMode==='week'?+r.week===week:r.month===month)&&(!trainer||r.trainer===trainer)&&(!q||`${r.trainer||''} ${r.specialty||''} ${r.course||''} ${r.code||''} ${(r.sections||[]).join(' ')} ${r.weekStatus||''}`.toLowerCase().includes(q)))}
function applyHead(){document.querySelector('#hfWeek')?.closest('label')?.classList.toggle('hidden',headMode!=='week');document.querySelector('#hfMonth')?.closest('label')?.classList.toggle('hidden',headMode!=='month');let filtered=getHeadFiltered(),grouped={};for(let r of filtered){let key=`${r.trainer}|${r.specialty||''}|${r.course}|${r.code||''}`;(grouped[key]??=[]).push(r)}currentVisibleRows=Object.entries(grouped).map(([key,a])=>{let [trainer,specialty,course,code]=key.split('|'),normal=a.filter(x=>!x.weekStatus||x.weekStatus==='normal'),statuses=[...new Set(a.map(x=>x.weekStatus).filter(x=>x&&x!=='normal'))];return {trainer,specialty,course,code,sections:[...new Set(a.flatMap(x=>x.sections||[]))].join('، '),interaction:weightedInteraction(normal),engaged:normal.reduce((n,x)=>n+Number(x.engaged||0),0),denom:normal.reduce((n,x)=>n+Number(x.opportunities||0),0),records:a.length,status:statuses.length?statuses.map(statusLabel).join('، '):'تقرير مهارة'}});let overall=weightedInteraction(filtered.filter(x=>!x.weekStatus||x.weekStatus==='normal')),submitted=[...new Set(filtered.map(r=>r.trainer).filter(Boolean))],expected=expectedTrainerNames(),selectedTrainer=document.querySelector('#hfTrainer')?.value||'',expectedVisible=selectedTrainer?expected.filter(x=>x===selectedTrainer):expected,missing=expectedVisible.filter(t=>!submitted.includes(t)),expectedCount=expectedVisible.length||submitted.length,submittedCount=expectedVisible.length?expectedVisible.filter(t=>submitted.includes(t)).length:submitted.length,trainerRate=expectedCount?submittedCount/expectedCount*100:null,courseCount=new Set(currentVisibleRows.map(r=>`${r.code||''}|${r.course||''}`)).size,sectionCount=new Set(currentVisibleRows.flatMap(r=>String(r.sections||'').split(/[،,]/).map(x=>`${r.code||r.course}|${x.trim()}`).filter(x=>!x.endsWith('|')))).size,rows=currentVisibleRows.map(r=>`<tr><td>${esc(r.trainer)}</td><td>${esc(r.specialty||'—')}</td><td>${esc(r.course)}<div class='tiny'>${esc(r.code)}</div></td><td>${esc(r.sections)}</td><td>${esc(r.status)}</td><td><b>${numPct(r.interaction)}</b></td></tr>`).join('');let missingBox=headMode==='week'?`<div class='card topgap'><div class='row between'><h3>المدربون الذين لم يرسلوا للأسبوع ${esc(document.querySelector('#hfWeek')?.value||'')}</h3><span class='badge'>${missing.length}</span></div><div>${missing.length?missing.map(x=>`<span class='badge'>${esc(x)}</span>`).join(' '):'<span class="muted">لا يوجد — جميع المدربين المتوقعين أرسلوا إفادتهم</span>'}</div></div>`:'';document.querySelector('#headResults').innerHTML=`<div class='grid topgap'><div class='card'><div class='muted'>المدربون المتوقعون</div><div class='kpi'>${expectedCount}</div></div><div class='card'><div class='muted'>أرسلوا الإفادة</div><div class='kpi'>${submittedCount}</div></div><div class='card'><div class='muted'>لم يرسلوا</div><div class='kpi'>${missing.length}</div></div><div class='card'><div class='muted'>نسبة تفاعل المدربين</div><div class='kpi'>${numPct(trainerRate)}</div></div><div class='card'><div class='muted'>نسبة تفاعل المتدربين</div><div class='kpi'>${numPct(overall)}</div></div><div class='card'><div class='muted'>عدد المقررات</div><div class='kpi'>${courseCount}</div></div><div class='card'><div class='muted'>عدد الشعب</div><div class='kpi'>${sectionCount}</div></div></div>${missingBox}<div class='card topgap tablewrap'><table><thead><tr><th>المدرب</th><th>التخصص</th><th>المقرر</th><th>الشعب</th><th>حالة الأسبوع</th><th>تفاعل المتدربين</th></tr></thead><tbody>${rows||'<tr><td colspan=6>لا توجد إفادات لهذه الفترة</td></tr>'}</tbody></table></div>`}
function statusLabel(x){return x==='no_skill'?'لا توجد مهارة':x==='continuing'?'مهارة مستمرة':'تقرير مهارة'}

async function importReports(files){for(const f of files){try{let r=JSON.parse(await f.text());if(r.type!=='motabe-summary')throw 0;upsertDepartmentReport(r)}catch{alert('أحد الملفات ليس تقرير متابع صالحًا')}}save();head()}
function cleanImportedText(v=''){let s=String(v??'');try{s=decodeURIComponent(s.replace(/\+/g,'%20'))}catch{s=s.replace(/\+/g,' ')}return s.replace(/\u00a0/g,' ').replace(/[\u200e\u200f]/g,'').replace(/\s+/g,' ').trim()}
