function nval(v){let n=Number(String(v??'').replace('%','').replace(',','.').trim());return Number.isFinite(n)?n:0}
function reportKey(r){let sections=[...(r.sections||[])].map(x=>norm(x)).filter(Boolean).sort().join('|');return [norm(r.trainer),norm(r.department||''),norm(r.course),norm(r.code||''),sections,Number(r.week)||0].join('§')}
function upsertDepartmentReport(r){let key=reportKey(r),idx=db.departmentReports.findIndex(x=>reportKey(x)===key);if(idx>=0){let old=db.departmentReports[idx],ot=Date.parse(old.createdAt||0)||0,nt=Date.parse(r.createdAt||0)||0;if(nt>=ot||!ot)db.departmentReports[idx]=r;return 'updated'}db.departmentReports.push(r);return 'added'}
