function sharepointDownloadCandidates(raw){let u=new URL(raw);u.searchParams.delete('web');u.searchParams.delete('action');let a=new URL(u);a.searchParams.set('download','1');let b=new URL(u);b.searchParams.set('download','true');return [a.toString(),b.toString(),u.toString()]}
async function fetchSharedExcel(raw){let lastErr=null;for(const url of sharepointDownloadCandidates(raw)){try{let r=await fetch(url,{method:'GET',redirect:'follow',credentials:'omit',cache:'no-store'});if(!r.ok)throw new Error('HTTP '+r.status);let blob=await r.blob();if(blob.size<100)throw new Error('empty');let ct=(r.headers.get('content-type')||'').toLowerCase();if(ct.includes('text/html'))throw new Error('html');return new File([blob],'forms-responses.xlsx',{type:blob.type||'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}catch(e){lastErr=e}}if(location.protocol!=='file:'){try{let r=await fetch('/api/excel',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({url:raw}),cache:'no-store'});if(!r.ok)throw new Error('proxy '+r.status);let blob=await r.blob();if(blob.size<100)throw new Error('empty');return new File([blob],'forms-responses.xlsx',{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}catch(e){lastErr=e}}throw lastErr||new Error('fetch')}
